    def get_settle_price(self, symbol, dt):
        """
        获取期货结算价格
        :param symbol:合约名称
        :type symbol: : str
        
        :param dt:指定日期
        :type dt: : datetime.date
        
        :return value:返回数据
        :type value: :float | np.nan
        """
        data = self.get_bar(symbol, dt, Frequency.DAILY.value, ['close'])
        if data is None:
            redata = np.nan
        else:
            redata = round(data[1], 2)
        return redata
    def get_prev_settlement(self, symbol, dt):
        """
        获取期货昨日结算价格
        :param symbol:合约名称
        :type symbol: : str
        
        :param dt:指定日期
        :type dt: : datetime.date
        
        :return value:返回数据
        :type value: :float | np.nan
        """
        all_trading_dates = self._get_trading_calendar()
        if dt in all_trading_dates:
            pre_dt = self._all_trading_dates_of_series.ix[:dt].ix[-2:-1].index[0]
        else:
            pre_dt = self._all_trading_dates_of_series.ix[:dt].ix[-1:].index[0]
        return self.get_settle_price(symbol, pre_dt)
